/**
 * 负责丘比特首夜恋人选择的请求、await 复验、关系绑定、成员归属与事实发布。
 * 输入为原夜上下文和经网关验证的配对；输出是同一关系记录及原事件，数据库存／选择写入由本族槽负责。
 * 原角色、容器、生命与双方 Victory 在等待前后复验；最终同步段依次绑定关系、消费选择、安装归属再发布。
 * 目标阵营按原点捕获并复验当前值，pairCamps仍是提交历史；不将关系／Victory当真实阵营。
 * 同步段不是事务：字段、组件或事件失败保留先完成的前缀，不退款或重新使用旧请求，殉情与判胜另有 owner。
 */
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import type { LoversComponent } from "../../../../core/domain/components/lovers";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getCupidState, commitCupidChoice } from "./state-slot";
import { bindLovers, hasCupidNightCommit } from "./relation";

export const CUPID_STAGE: NightStageHandler = {
  id: "cupid",
  priority: 80,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    if (hasCupidNightCommit(ctx.world, day)) throw new Error("cupid_night_reentry_after_commit");
    for (const actorId of ctx.getAliveByRole(Role.Cupid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getCupidState(role),
        life = captureNightLife(ctx.world, actorId),
        victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        policy = state.policy,
        affiliations = victory.affiliations,
        membership = JSON.stringify(affiliations);
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Cupid &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getCupidState(role) === state &&
        state.policy === policy &&
        state.remaining === 1 &&
        state.choice === null &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        JSON.stringify(affiliations) === membership &&
        !hasCupidNightCommit(ctx.world, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world.getAliveEntityIds().map((id) => {
            const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!,
              targetVictory = ctx.world.getComponent(id, COMPONENT.Victory)!;
            return [
              id,
              {
                life: captureNightLife(ctx.world, id)!,
                role: targetRole,
                kind: targetRole.role,
                camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                privateState: targetRole.privateState,
                victory: targetVictory,
                affiliations: targetVictory.affiliations,
                membership: JSON.stringify(targetVictory.affiliations),
              },
            ] as const;
          }),
        );
        if (targets.size < 2) throw new Error("cupid_valid_action_missing");
        const request = ctx.makeRequest(actorId, ["choose_lovers"], {
          stage: "cupid",
          requiresAction: true,
          allow_fallback: false,
          action_failure_policy: "error",
          ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
        });
        if (!current()) break;
        const action = await ctx.actionProvider.getAction(request);
        if (!current()) break;
        if (action?.name !== "choose_lovers") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_lovers") continue;
        const pairIds: [number, number] = [
          valid.sanitizedCall.args.first_id,
          valid.sanitizedCall.args.second_id,
        ];
        const selected = pairIds.map((id) => targets.get(id));
        if (
          selected.some(
            (target, index) =>
              !target ||
              !livingNightLife(ctx.world, target.life) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Role) !== target.role ||
              target.role.role !== target.kind ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Camp)?.camp !== target.camp ||
              target.role.privateState !== target.privateState ||
              (target.camp !== Camp.Good && target.camp !== Camp.Wolf) ||
              ctx.world.getComponent(pairIds[index]!, COMPONENT.Victory) !== target.victory ||
              target.victory.affiliations !== target.affiliations ||
              JSON.stringify(target.affiliations) !== target.membership,
          )
        )
          continue;
        const first = selected[0]!,
          second = selected[1]!,
          mixed = first.camp !== second.camp;
        const record: LoversComponent = Object.freeze({
          actorId,
          day: 1,
          policy,
          pairIds: Object.freeze(pairIds),
          pairCamps: Object.freeze([first.camp, second.camp]) as LoversComponent["pairCamps"],
          groupId: "cupid_lovers",
          mixed,
        });
        const memberIds = new Set(pairIds);
        if (policy === "netease_2017_cupid_follows_lovers_v1") memberIds.add(actorId);
        // 最后授权后不再 await；关系先绑定，选择随后付款，再逐成员安装归属。失败不撤回已完成的前缀。
        bindLovers(ctx.world, record, [first.life, second.life]);
        commitCupidChoice(state, pairIds);
        for (const id of memberIds)
          ctx.world.addComponent(
            id,
            COMPONENT.Victory,
            createVictoryComponent([
              mixed
                ? { kind: "relationship", groupId: record.groupId }
                : { kind: "faction", faction: first.camp! },
            ]),
          );
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_lovers_chosen",
          payload: { actorId, day: 1, pairIds: [...pairIds] },
        });
        for (const id of pairIds)
          ctx.events.push({
            timestamp: Date.now(),
            type: "lover_recognized",
            payload: { actorId: id, partnerId: pairIds.find((target) => target !== id)! },
          });
        ctx.events.push({
          timestamp: Date.now(),
          type: "cupid_relation_resolved",
          payload: record,
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("cupid_valid_action_missing");
    }
  },
};

/**
 * 负责 丘比特 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { CUPID_POLICIES } from "../../../../core/domain/board";
import { Camp, Role, Phase, WinCondition } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { getCupidState, projectCupidState, installCupidState } from "./state-slot";
import { hasCupidNightCommit } from "./relation";
import { CUPID_STAGE } from "./night_stage";
const parameters = z.strictObject({
  policy: z.enum(CUPID_POLICIES).default("netease_2017_cupid_follows_lovers_v1"),
});
export const CUPID_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Cupid,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("cupid"),
    skillBrief: text("zh-CN", "role.cupid.brief"),
    supportedWinConditions: [WinCondition.SlaughterCity],
    supportedBoardRoles: [
      Role.Cupid,
      Role.Wolf,
      Role.WolfKing,
      Role.WhiteWolfKing,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
      Role.Knight,
      Role.Dreamer,
      Role.WolfBeauty,
    ],
  },
  runtime: {
    init: installCupidState,
    configuration: {
      schema: parameters,
      defaults: { policy: "netease_2017_cupid_follows_lovers_v1" },
      apply: (config, value) => ({ ...config, cupid: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.cupid ?? {}),
    },
    nightStages: [CUPID_STAGE],
    toolSpecs: [
      {
        name: "choose_lovers",
        parameters: {
          type: "object",
          properties: { first_id: { type: "integer" }, second_id: { type: "integer" } },
          required: ["first_id", "second_id"],
          additionalProperties: false,
        },
        argHint: 'choose_lovers args: {"first_id":number,"second_id":number}',
        userPromptHintKey: "action.choose_lovers.hint",
      },
    ],
    validationRules: {
      choose_lovers: (ctx) => {
        const { world, role, day, phase, toolCall } = ctx;
        const state = getCupidState(role);
        if (
          role.role !== Role.Cupid ||
          world.getComponent(ctx.actorId, COMPONENT.Camp)?.camp !== Camp.Good ||
          !state ||
          state.remaining !== 1 ||
          state.choice !== null ||
          day !== 1 ||
          hasCupidNightCommit(world, day)
        )
          return { code: RuleError.CupidUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "choose_lovers") return { code: RuleError.ToolMismatch };
        const { first_id, second_id } = toolCall.args;
        if (
          !Number.isSafeInteger(first_id) ||
          !Number.isSafeInteger(second_id) ||
          first_id === second_id ||
          !isAliveTarget(world, first_id) ||
          !isAliveTarget(world, second_id)
        )
          return { code: RuleError.CupidTarget };
        return null;
      },
    },
    baselineAction: (_role, request, _other, _camp, _locale, world) => {
      if (!request.allowedTools.includes("choose_lovers") || !world) return null;
      const ids = world.getAliveEntityIds();
      return ids.length < 2
        ? null
        : { name: "choose_lovers", args: { first_id: ids[0]!, second_id: ids[1]! } };
    },
    llmRepair: {
      coerce: {
        choose_lovers: (args) => {
          const first = numberOrNull(args.first_id),
            second = numberOrNull(args.second_id);
          return first === null || second === null ? null : { first_id: first, second_id: second };
        },
      },
    },
  },
  presentation: nativeRolePresentation("cupid"),
};

/**
 * 负责混血儿首夜榜样选择的请求、原体／目标复验及隐藏胜利归属安装。
 * 输入为当前夜上下文和经网关验证的榜样；输出为已选数据、独立归属和原事实，不改变角色或真实阵营。
 * 等待前后仍核原容器、状态、生命和空 Victory；先构造归属，再由本族槽消费次数／写选择，随后安装组件。
 * 目标阵营按原点捕获并复验真实 Camp 值，安装的是独立Victory归属，不写当前阵营。
 * 同步字段与组件提交失败保留已写前缀；夜提交账本和事件仍在原安装之后，不以玩家知识恢复许可。
 */
import { COMPONENT } from "../../../../core/domain/components/names";

import {
  createVictoryComponent,
  type VictoryComponent,
} from "../../../../core/domain/components/victory";
import { Camp, Phase, Role } from "../../../../core/domain/model";
import { captureNightLife, livingNightLife } from "../../../../core/domain/night_effects";
import type { World } from "../../../../core/domain/world";
import type { NightStageHandler } from "../../stages/night/contracts";
import { canChooseExemplar, getHybridState, commitHybridChoice } from "./state-slot";

const committed = new WeakMap<World, Set<number>>();
export function hasHybridNightCommit(world: World, day: number): boolean {
  return committed.get(world)?.has(day) ?? false;
}

export const HYBRID_STAGE: NightStageHandler = {
  id: "hybrid",
  priority: 110,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (day !== 1) return;
    for (const actorId of ctx.getAliveByRole(Role.Hybrid)) {
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!;
      const state = getHybridState(role),
        life = captureNightLife(ctx.world, actorId);
      const victory = ctx.world.getComponent(actorId, COMPONENT.Victory);
      if (!state || !life || !victory || ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good) continue;
      const privateState = role.privateState,
        affiliations = victory.affiliations;
      const current = () =>
        ctx.isCurrent() &&
        ctx.currentDay() === day &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.Hybrid &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Good &&
        role.privateState === privateState &&
        getHybridState(role) === state &&
        livingNightLife(ctx.world, life) &&
        ctx.world.getComponent(actorId, COMPONENT.Victory) === victory &&
        victory.affiliations === affiliations &&
        affiliations.length === 0 &&
        canChooseExemplar(state, day);
      if (!current()) continue;
      let completed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        if (!current()) break;
        const targets = new Map(
          ctx.world
            .getAliveEntityIds()
            .filter((id) => id !== actorId)
            .map((id) => {
              const targetRole = ctx.world.getComponent(id, COMPONENT.Role)!;
              return [
                id,
                {
                  life: captureNightLife(ctx.world, id)!,
                  role: targetRole,
                  kind: targetRole.role,
                  camp: ctx.world.getComponent(id, COMPONENT.Camp)?.camp,
                  privateState: targetRole.privateState,
                },
              ] as const;
            }),
        );
        if (!targets.size) throw new Error("hybrid_valid_action_missing");
        const action = await ctx.actionProvider.getAction(
          ctx.makeRequest(actorId, ["choose_exemplar"], {
            stage: "hybrid",
            requiresAction: true,
            allow_fallback: false,
            ...(attempt ? { retry_attempt: attempt, retry_max: 2 } : {}),
          }),
        );
        if (!current()) break;
        if (action?.name !== "choose_exemplar") continue;
        const valid = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !valid.ok || valid.sanitizedCall?.name !== "choose_exemplar") continue;
        const targetId = valid.sanitizedCall.args.target_id,
          target = targets.get(targetId);
        if (
          !target ||
          !livingNightLife(ctx.world, target.life) ||
          ctx.world.getComponent(targetId, COMPONENT.Role) !== target.role ||
          target.role.role !== target.kind ||
          ctx.world.getComponent(targetId, COMPONENT.Camp)?.camp !== target.camp ||
          target.role.privateState !== target.privateState ||
          (target.camp !== Camp.Good && target.camp !== Camp.Wolf)
        )
          continue;
        const membership = createVictoryComponent([{ kind: "faction", faction: target.camp! }]);
        // 最后复验到两字段写入之间没有 await；同一原体的第二个回复不能复用已消费的选择。
        commitHybridChoice(state, day, targetId);
        ctx.world.addComponent(actorId, COMPONENT.Victory, membership);
        const days = committed.get(ctx.world) ?? new Set<number>();
        days.add(day);
        committed.set(ctx.world, days);
        ctx.events.push({
          timestamp: Date.now(),
          type: "hybrid_exemplar_chosen",
          payload: { actorId, day, targetId },
        });
        ctx.events.push({
          timestamp: Date.now(),
          type: "hybrid_affiliation_resolved",
          payload: { actorId, day, targetId, faction: target.camp },
        });
        completed = true;
        break;
      }
      if (!completed && current()) throw new Error("hybrid_valid_action_missing");
    }
  },
};

/**
 * 负责 混血儿 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { VictoryComponent } from "../../../../core/domain/components/victory";
import { Camp, Role, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { canChooseExemplar, getHybridState, projectHybridState, installHybridState } from "./state-slot";
import { HYBRID_STAGE } from "./night_stage";

export const HYBRID_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Hybrid,
    camp: Camp.Good,
    goodSide: "villager",
    maxCount: 1,
    label: roleName("hybrid"),
    skillBrief: text("zh-CN", "role.hybrid.brief"),
    supportedBoardRoles: [
      Role.Hybrid,
      Role.Wolf,
      Role.WolfKing,
      Role.HiddenWolf,
      Role.Seer,
      Role.Witch,
      Role.Guard,
      Role.Hunter,
      Role.Idiot,
      Role.Villager,
    ],
  },
  runtime: {
    initialVictoryAffiliations: [],
    init: installHybridState,
    configuration: {
      schema: z.strictObject({}),
      defaults: {},
      apply: (config) => config,
      serialize: () => ({}),
    },
    nightStages: [HYBRID_STAGE],
    toolSpecs: [
      {
        name: "choose_exemplar",
        parameters: {
          type: "object",
          properties: { target_id: { type: "integer" } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'choose_exemplar args: {"target_id":number}',
        userPromptHintKey: "action.choose_exemplar.hint",
      },
    ],
    validationRules: {
      choose_exemplar: ({ world, actorId, role, day, phase, toolCall }) => {
        const state = getHybridState(role),
          victory = world.getComponent(actorId, COMPONENT.Victory);
        if (
          role.role !== Role.Hybrid ||
          world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Good ||
          !state ||
          day === undefined ||
          !canChooseExemplar(state, day) ||
          !victory ||
          victory.affiliations.length !== 0
        )
          return { code: RuleError.HybridUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "choose_exemplar") return { code: RuleError.ToolMismatch };
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.HybridTarget };
        return null;
      },
    },
    llmRepair: {
      coerce: {
        choose_exemplar: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
  },
  presentation: nativeRolePresentation("hybrid"),
};

/**
 * 负责狼美人夜间魅惑的请求、等待后原体复验、选择历史、关系绑定及公开／动物私密通知。
 * 输入为原夜上下文与经网关验证的可空目标；输出保留原历史、绑定与事件，拒绝或失效选择不安装新关系。
 * 动物准入与板子识别通过查询端口按原位置调用，通知通过独立事实端口发表，不能将已知数据当作现场权限。
 * 原状态先写历史，再绑定关系、发表 charm_applied，最后按板子追加通知；后续失败不撤销已完成前缀或补发事实。
 * 目标和演员生命版本在原等待前后核对；本流程不提前领取死亡牵连，实际来源政策、保护与标死另归原 owner。
 */
import { recordCharmSelection } from "./state";
import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Role, Camp, Phase } from "../../../../core/domain/model";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { NightStageHandler } from "../../stages/night/contracts";
import { getWolfBeautyState } from "./state";
import { bindCharm } from "./relation";
import { animalBeautyCharmAllowed, isAnimalDreamBoard } from "../animal_dream/beauty-query-ports";
import { appendAnimalBeautyNotice } from "../animal_dream/beauty-fact-ports";

export const WOLF_BEAUTY_CHARM_STAGE: NightStageHandler = {
  id: "wolf_beauty_charm",
  priority: 450,
  async execute(ctx) {
    const day = ctx.currentDay();
    if (!animalBeautyCharmAllowed(ctx.world, day)) return;
    for (const actorId of ctx.getAliveByRole(Role.WolfBeauty)) {
      if (!ctx.isCurrent()) return;
      const role = ctx.world.getComponent(actorId, COMPONENT.Role)!,
        state = getWolfBeautyState(role),
        actorLife = ctx.world.getComponent(actorId, COMPONENT.Alive)!,
        actorVersion = aliveLifeVersion(actorLife),
        policy = state?.deathLinkPolicy;
      if (ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf || !state || state.lastActedDay === day) continue;
      const targets = new Map(
        ctx.world
          .getAliveEntityIds()
          .filter((id) => id !== actorId)
          .map((id) => {
            const life = ctx.world.getComponent(id, COMPONENT.Alive)!;
            return [id, { life, version: aliveLifeVersion(life) }] as const;
          }),
      );
      const action = await ctx.actionProvider.getAction(
        ctx.makeRequest(actorId, ["charm"], { stage: "wolf_beauty", requiresAction: false }),
      );
      const current = () =>
        ctx.isCurrent() &&
        animalBeautyCharmAllowed(ctx.world, day) &&
        ctx.world.getComponent(actorId, COMPONENT.Role) === role &&
        role.role === Role.WolfBeauty &&
        ctx.world.getComponent(actorId, COMPONENT.Camp)?.camp === Camp.Wolf &&
        getWolfBeautyState(role) === state &&
        state.deathLinkPolicy === policy &&
        state.lastActedDay !== day &&
        ctx.world.getComponent(actorId, COMPONENT.Alive) === actorLife &&
        actorLife.alive &&
        actorVersion !== undefined &&
        aliveLifeVersion(actorLife) === actorVersion;
      if (!current()) continue;
      if (action !== null && action.name !== "charm") continue;
      let targetId = action === null ? null : action.args.target_id;
      if (action) {
        const result = ctx.toolGateway.validateAndSanitize(ctx.world, actorId, action, {
          phase: Phase.Night,
          day,
        });
        if (!current() || !result.ok || result.sanitizedCall?.name !== "charm") continue;
        targetId = result.sanitizedCall.args.target_id;
      }
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          ctx.world.getComponent(targetId, COMPONENT.Alive) !== target.life ||
          !target.life.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.life) !== target.version
        )
          continue;
      }
      recordCharmSelection(state, targetId, day);
      bindCharm(ctx.world, actorId, targetId);
      ctx.events.push({
        timestamp: Date.now(),
        type: "charm_applied",
        payload: { actorId, targetId, day },
      });
      if (isAnimalDreamBoard(ctx.world)) appendAnimalBeautyNotice(ctx.world, ctx.events, day);
    }
  },
};

/**
 * 负责 狼美人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { BEAUTY_DEATH_LINK_POLICIES } from "../../../../core/domain/board";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Role, Camp, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getWolfBeautyState, setWolfBeautyState } from "./state";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { WOLF_VALIDATION_RULES } from "../wolf/ability-ports";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";
import { WOLF_BEAUTY_CHARM_STAGE } from "./night_stages";
import { wolfBeautyDeathHook } from "./death_hook";
import { animalBeautyCharmAllowed, isAnimalDreamBoard } from "../animal_dream/beauty-query-ports";
import { animalBeautyKnowledge } from "../animal_dream/beauty-fact-ports";
import { COMPONENT } from "../../../../core/domain/components/names";

const parameters = z.strictObject({
  deathLinkPolicy: z.enum(BEAUTY_DEATH_LINK_POLICIES).default("awa_exile_poison_v1"),
});

export const WOLF_BEAUTY_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.WolfBeauty,
    label: roleName("wolf_beauty"),
    skillBrief: text("zh-CN", "role.wolf_beauty.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    init: (role, ctx) => {
      setWolfBeautyState(role, {
        targetId: null,
        lastActedDay: null,
        history: [],
        ...(ctx.boardConfig?.wolfBeauty?.deathLinkPolicy &&
        ctx.boardConfig.wolfBeauty.deathLinkPolicy !== "awa_exile_poison_v1"
          ? { deathLinkPolicy: ctx.boardConfig.wolfBeauty.deathLinkPolicy }
          : {}),
      });
    },
    configuration: {
      schema: parameters,
      defaults: { deathLinkPolicy: "awa_exile_poison_v1" },
      apply: (config, value) => ({ ...config, wolfBeauty: parameters.parse(value) }),
      serialize: (config) => parameters.parse(config.wolfBeauty ?? {}),
    },
    nightStages: [...ORDINARY_WOLF_CONTRIBUTIONS.runtime.nightStages!, WOLF_BEAUTY_CHARM_STAGE],
    deathHook: wolfBeautyDeathHook,
    toolSpecs: [
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs!.filter((spec) => spec.name !== "self_destruct"),
      {
        name: "charm",
        parameters: {
          type: "object",
          properties: { target_id: { type: ["number", "null"] } },
          required: ["target_id"],
          additionalProperties: false,
        },
        argHint: 'charm args: {"target_id":number|null}',
        userPromptHintKey: "action.charm.hint",
      },
    ],
    validationRules: {
      ...WOLF_VALIDATION_RULES,
      kill_vote: (ctx) => {
        const inherited = WOLF_VALIDATION_RULES.kill_vote!(ctx);
        if (inherited) return inherited;
        return ctx.toolCall.name === "kill_vote" &&
          !ctx.toolCall.args.abstain &&
          ctx.toolCall.args.target_id === ctx.actorId
          ? { code: RuleError.BeautySelfKnife }
          : null;
      },
      // 原状态／角色检查后才查询动物魅惑准入；它不等于已发表知识，也不跳过后续 phase／目标／连续夜校验。
      charm: ({ world, actorId, role, phase, day, toolCall }) => {
        const state = getWolfBeautyState(role);
        if (
          role.role !== Role.WolfBeauty ||
          world.getComponent(actorId, COMPONENT.Camp)?.camp !== Camp.Wolf ||
          !state ||
          !animalBeautyCharmAllowed(world, day ?? 0) ||
          state.lastActedDay === day
        )
          return { code: RuleError.CharmUnavailable };
        if (phase !== Phase.Night) return { code: RuleError.AbilityPhase };
        if (toolCall.name !== "charm") return { code: RuleError.ToolMismatch };
        if (toolCall.args.target_id === null) return null;
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.CharmTarget };
        const previous = state.history.at(-1);
        return previous?.day === (day ?? 1) - 1 && previous.targetId === toolCall.args.target_id
          ? { code: RuleError.CharmRepeat }
          : null;
      },
    },
    llmRepair: {
      coerce: {
        ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.llmRepair?.coerce,
        charm: (args) => {
          if (args.target_id === null) return { target_id: null };
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target };
        },
      },
    },
    baselineAction: (role, request, pick, byCamp, locale, _world, currentCamp) => {
      if (request.allowedTools.includes("charm")) {
        const target = pick(),
          previous = getWolfBeautyState(role)?.history.at(-1);
        return {
          name: "charm",
          args: {
            target_id:
              previous?.day === request.context.day - 1 && previous.targetId === target
                ? null
                : target,
          },
        };
      }
      return ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction!(role, request, pick, byCamp, locale, undefined, currentCamp);
    },
  },
  presentation: nativeRolePresentation("wolf_beauty"),
};

/**
 * 负责恋人原生命绑定、已授权关系查询及殉情死亡闭包。输入为原 World、关系记录、死因与梦效果句柄；
 * 输出为仍当前的关系、追加死因和逐关联去重的事件，bindings 唯一持有关系及 emitted 前缀。
 * 殉情保原独立根／来源规则，梦关系通过运行接口在原时点参与闭包；不复制效果、不标死或判胜。
 */
import { COMPONENT } from "../../../../core/domain/components/names";
import { aliveLifeVersion } from "../../../../core/domain/components/alive";
import type { LoversComponent } from "../../../../core/domain/components/lovers";
import type { World } from "../../../../core/domain/world";
import type { NightLifeScope } from "../../../../core/domain/night_effects";
import {
  DeathCause,
  type DeathSources,
  type EntityId,
  type GameEvent,
} from "../../../../core/domain/model";
import type { DreamNightEffects } from "../../../../core/domain/dream-night-effects";

interface Binding {
  record: LoversComponent;
  lives: readonly [NightLifeScope, NightLifeScope];
  emitted: Set<string>;
}
const bindings = new WeakMap<World, Binding>();
export function bindLovers(
  world: World,
  record: LoversComponent,
  lives: readonly [NightLifeScope, NightLifeScope],
): void {
  if (bindings.has(world)) throw new Error("cupid_relation_already_committed");
  world.addComponent(record.actorId, COMPONENT.Lovers, record);
  bindings.set(world, { record, lives, emitted: new Set() });
}
export function hasCupidNightCommit(world: World, day: number): boolean {
  return day === 1 && bindings.has(world);
}
export function projectLover(world: World, actorId: EntityId) {
  const binding = bindings.get(world),
    record = loversRecord(world);
  const life = binding?.lives.find((scope) => scope.id === actorId);
  return record && life && binding!.lives.every((scope) => sameBody(world, scope))
    ? {
        partnerId: record.pairIds.find((id) => id !== actorId)!,
        mayNotVotePartner: record.policy === "lui_meme_lovers_only_v1",
      }
    : null;
}
export function loversRecord(world: World): LoversComponent | null {
  const binding = bindings.get(world);
  return binding && world.getComponent(binding.record.actorId, COMPONENT.Lovers) === binding.record
    ? binding.record
    : null;
}
function sameBody(world: World, scope: NightLifeScope): boolean {
  return (
    world.getComponent(scope.id, COMPONENT.Alive) === scope.life &&
    aliveLifeVersion(scope.life) === scope.version + (scope.life.alive ? 0 : 1)
  );
}
export function livingOriginalLovers(world: World): boolean {
  const binding = bindings.get(world);
  return (
    !!loversRecord(world) &&
    !!binding?.lives.every((scope) => sameBody(world, scope) && scope.life.alive)
  );
}
export function prohibitsLoversVote(world: World, actor: EntityId, target: EntityId): boolean {
  const binding = bindings.get(world),
    record = loversRecord(world);
  return (
    !!record &&
    record.policy === "lui_meme_lovers_only_v1" &&
    !!binding?.lives.every((scope) => sameBody(world, scope) && scope.life.alive) &&
    record.pairIds.includes(actor) &&
    record.pairIds.includes(target) &&
    actor !== target
  );
}
/** 在枪／遗言／死亡钩子前展开外部死因波；殉情不作为独立根去抑制原来源。
 * 已付摄梦关系可追加独立根，闭包仍以原 ID／死因为界；运行梦接口不复制或重新支付效果。 */
export function expandLoversWave(
  world: World,
  ids: EntityId[],
  sources: DeathSources,
  events: GameEvent[],
  nightOrigin: Set<EntityId>,
  eligibleDead: ReadonlySet<EntityId>,
  dreams?: DreamNightEffects,
): EntityId[] {
  if (!loversRecord(world)) return [];
  const before = new Set(ids),
    members = new Set(ids),
    roots = new Set(ids);
  const binding = bindings.get(world),
    record = loversRecord(world);
  const expandedRoots = new Set<EntityId>();
  let changed = true;
  while (changed) {
    changed = false;
    if (record && binding && binding.lives.every((scope) => sameBody(world, scope))) {
      const independentPair = record.pairIds.every((id) => roots.has(id));
      for (const root of record.pairIds) {
        if (!roots.has(root) || expandedRoots.has(root)) continue;
        expandedRoots.add(root);
        const target = record.pairIds.find((id) => id !== root)!;
        const targetLife = binding.lives.find((scope) => scope.id === target)!;
        if (!targetLife.life.alive && !members.has(target) && !eligibleDead.has(target)) continue;
        if (!members.has(target)) {
          members.add(target);
          ids.push(target);
          changed = true;
        }
        if (!roots.has(target) || independentPair) {
          if (!(sources[target] ?? []).includes(DeathCause.Lovers)) {
            sources[target] = [...(sources[target] ?? []), DeathCause.Lovers];
            changed = true;
          }
          if (nightOrigin.has(root)) nightOrigin.add(target);
          const key = `${root}:${target}`;
          if (!binding.emitted.has(key)) {
            binding.emitted.add(key);
            events.push({
              timestamp: Date.now(),
              type: "lovers_death",
              payload: { actorId: root, targetId: target },
            });
          }
        }
      }
    }
    if (dreams && nightOrigin.size) {
      for (const id of dreams.linkedDeaths(
        world,
        [...nightOrigin],
        new Set([...eligibleDead, ...members]),
      )) {
        if (!members.has(id)) {
          members.add(id);
          ids.push(id);
          changed = true;
        }
        if (!(sources[id] ?? []).includes(DeathCause.Dream)) {
          sources[id] = [...(sources[id] ?? []), DeathCause.Dream];
          changed = true;
        }
        if (!roots.has(id)) {
          roots.add(id);
          changed = true;
        }
        nightOrigin.add(id);
      }
    }
  }
  return ids.filter((id) => !before.has(id));
}

controls.text:
/**
 * 记录身份安装失败后已退休的 Role 运行授权；输入为实际组件对象，输出为永久退休标记与拒绝查询。
 * 只有具体安装 writer 在声明的核心失败边界标记，字段恢复或跨 World 复用同对象都不能清除；新对象仍须经过各自许可校验。
 * 私有集合不保存 Camp、World、库存或快照，不改组件属性；false 仅表示未被该失败政策退休，不代表可以执行行动。
 * 纯数据、已付效果的原体复验、目标身份、观察、归档和死亡清理各保原职责；正常组件变化不自动退休。
 */
import type { RoleComponent } from "./components/role";

// 用对象身份记录不可恢复的执行终态；不写公开字段，冻结的组件也能保留最初安装错误。
const retiredExecutions = new WeakSet<RoleComponent>();

/** 受信任的身份安装 writer 专用；重复退休幂等，不回滚已经完成的组件、库存或事实前缀。 */
export function retireRoleExecution(role: RoleComponent): void {
  retiredExecutions.add(role);
}

/** 仅提供拒绝条件，调用方仍须按原顺序检查生命、来源、资源、阶段及实际提交资格。 */
export function isRoleExecutionRetired(role: RoleComponent): boolean {
  return retiredExecutions.has(role);
}

/**
 * 负责实体 ID、组件 Map 与原生命绑定的临时死亡行动许可。输入为既有实体／槽操作及
 * 生命周期回调，输出保持原可写组件引用、筛选结果和许可 ID。World 唯一写入自己的存储，
 * 工厂与角色所有者仍负责值和资源校验；槽推断不增加运行守卫、复制或冻结。
 * 旧任意组件类型 T 重载已退出，读写关系由具名槽约束；死亡许可仍按原生命版本与当前性撤销，ID 本身不授权。
 */
import { EntityId, Phase, Role } from "./model";
import { COMPONENT, ComponentName } from "./components/names";
import type { ComponentMap, ComponentWrite } from "./component-map";
import { AliveComponent, aliveLifeVersion } from "./components/alive";
import { RoleComponent } from "./components/role";
import { isLocale, type Locale } from "@ai-werewolf-arena/game-contract";

/**
 * World 是 ECS 内存状态容器。
 * 设计目标：保持结构简单、读写明确，所有系统都基于该容器进行组件查询与变更。
 */
export class World {
  constructor(readonly locale: Locale = "zh-CN") {
    if (!isLocale(locale)) throw new Error("game_locale_invalid");
  }
  private nextId: EntityId = 1;
  private entities: Set<EntityId> = new Set();
  private stores: Map<ComponentName, Map<EntityId, unknown>> = new Map();
  private nextDeathActionId = 1;
  // 许可绑定原 Alive 对象和该对象的生命版本；复活、替换组件或失去当前性均撤销旧许可。
  private deathActions = new Map<
    EntityId,
    {
      id: number;
      tool: "shoot" | "speak" | "choose_badge_successor";
      phase: Phase;
      day: number;
      abilityId?: string;
      alive: AliveComponent;
      lifeVersion: number;
      isCurrent: () => boolean;
    }
  >();

  /** 引擎拥有的临时行动许可；ID 不授予行动。World 复核原生命与传入的当前性回调，带阶段的查询另核许可记录的 phase／day。 */
  openDeathAction(
    actorId: EntityId,
    tool: "shoot" | "speak" | "choose_badge_successor",
    phase: Phase,
    day: number,
    isCurrent: () => boolean = () => true,
    abilityId?: string,
  ): { readonly id: number; close(): void } {
    if (this.currentDeathAction(actorId)) throw new Error("death_action_already_open");
    const alive = this.getComponent(actorId, COMPONENT.Alive);
    const lifeVersion = alive && aliveLifeVersion(alive);
    if (
      !alive ||
      alive.alive !== false ||
      lifeVersion === undefined ||
      !this.getComponent(actorId, COMPONENT.Role) ||
      !Number.isSafeInteger(day) ||
      day < 1 ||
      !["shoot", "speak", "choose_badge_successor"].includes(tool) ||
      !Object.values(Phase).includes(phase) ||
      phase === Phase.GameOver ||
      (abilityId !== undefined &&
        (tool !== "shoot" ||
          typeof abilityId !== "string" ||
          !/^[a-z][a-z0-9:_-]{0,127}$/.test(abilityId) ||
          abilityId.startsWith("native:")))
    ) {
      throw new Error("death_action_invalid_actor_or_stage");
    }
    const id = this.nextDeathActionId++;
    this.deathActions.set(actorId, {
      id,
      tool,
      phase,
      day,
      abilityId,
      alive,
      lifeVersion,
      isCurrent,
    });
    return Object.freeze({
      id,
      close: () => {
        if (this.deathActions.get(actorId)?.id === id) this.deathActions.delete(actorId);
      },
    });
  }

  hasDeathAction(
    actorId: EntityId,
    tool: string,
    phase: Phase,
    day: number | undefined,
    id: number | undefined,
    abilityId?: string,
  ): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.phase === phase &&
      permit.day === day &&
      permit.abilityId === abilityId
    );
  }

  isDeathActionOpen(actorId: EntityId, tool: string, id: number, abilityId?: string): boolean {
    const permit = this.currentDeathAction(actorId);
    return (
      permit !== undefined &&
      permit.id === id &&
      permit.tool === tool &&
      permit.abilityId === abilityId
    );
  }

  private currentDeathAction(actorId: EntityId) {
    const permit = this.deathActions.get(actorId);
    if (!permit) return undefined;
    if (
      this.getComponent(actorId, COMPONENT.Alive) !== permit.alive ||
      permit.alive.alive !== false ||
      aliveLifeVersion(permit.alive) !== permit.lifeVersion ||
      !permit.isCurrent()
    ) {
      this.deathActions.delete(actorId);
      return undefined;
    }
    return permit;
  }

  get activeDeathActionCount(): number {
    for (const actorId of this.deathActions.keys()) this.currentDeathAction(actorId);
    return this.deathActions.size;
  }

  closeDeathActions(): void {
    this.deathActions.clear();
  }

  /**
   * 创建新实体并返回实体 ID。
   */
  createEntity(): EntityId {
    const id = this.nextId++;
    this.entities.add(id);
    return id;
  }

  /**
   * 判断实体是否存在。
   */
  hasEntity(entityId: EntityId): boolean {
    return this.entities.has(entityId);
  }

  /**
   * 返回当前所有实体 ID（升序）。
   */
  entityIds(): EntityId[] {
    return [...this.entities].sort((a, b) => a - b);
  }

  addComponent<K extends ComponentName, C extends ComponentWrite<NoInfer<K>>>(
    entityId: EntityId,
    name: K,
    component: C,
  ): void {
    if (!this.hasEntity(entityId)) {
      throw new Error(`Entity ${entityId} does not exist`);
    }

    // 每类组件一张表，按 entityId 索引。
    const store = this.ensureStore(name);
    store.set(entityId, component);
  }

  getComponent<K extends ComponentName>(entityId: EntityId, name: K): ComponentMap[K] | undefined {
    const store = this.stores.get(name);
    return store?.get(entityId) as ComponentMap[K] | undefined;
  }

  /**
   * 从实体上移除指定组件。
   */
  removeComponent(entityId: EntityId, name: ComponentName): void {
    const store = this.stores.get(name);
    store?.delete(entityId);
  }

  /**
   * 返回同时拥有给定组件集合的实体列表。
   */
  entitiesWith(...names: ComponentName[]): EntityId[] {
    // 只有同时拥有所有组件的实体才会被返回，用于系统筛选。
    return this.entityIds().filter((entityId) => {
      return names.every((name) => {
        const store = this.stores.get(name);
        return store?.has(entityId) ?? false;
      });
    });
  }

  /**
   * 返回当前存活实体 ID 列表。
   */
  getAliveEntityIds(): EntityId[] {
    return this.entitiesWith(COMPONENT.Alive).filter((id) => {
      const alive = this.getComponent(id, COMPONENT.Alive);
      return alive?.alive === true;
    });
  }

  /**
   * 按角色筛选实体 ID。
   */
  getEntityIdsByRole(role: Role): EntityId[] {
    return this.entitiesWith(COMPONENT.Role).filter((id) => {
      const roleComp = this.getComponent(id, COMPONENT.Role);
      return roleComp?.role === role;
    });
  }

  /**
   * 确保组件存储存在，不存在则懒加载创建。
   */
  private ensureStore(name: ComponentName): Map<EntityId, unknown> {
    let store = this.stores.get(name);
    if (!store) {
      // 延迟初始化组件存储，避免为未使用组件提前分配空间。
      store = new Map<EntityId, unknown>();
      this.stores.set(name, store);
    }
    return store;
  }
}

/**
 * 负责运行时夜间效果声明、原生命身份检查与机械伤害折叠。
 * 输入为原组件引用和已付效果；输出为有来源的 intent、原生命版本及保序伤害折叠。
 * 新 owned intent 消费类别／夜时点／原体因果链，旧注入对象保留原读取和接受宽度。
 * 所有者保留资源提交权限，句柄不进入序列化或玩家知识，本模块不将玩家标记为死亡。
 */
import type { DeathCause } from "./deaths";
import { COMPONENT } from "./components/names";
import { aliveLifeVersion, type AliveComponent } from "./components/alive";
import type { World } from "./world";
import type { EntityId } from "./identity";
import type { StatusMarksComponent } from "./components/status_marks";

/** 查询原生命和印记身份，不暴露组件修改命令。 */
export interface NightEffectQuery {
  getComponent(id: EntityId, name: typeof COMPONENT.Alive): Readonly<AliveComponent> | undefined;
  getComponent(id: EntityId, name: typeof COMPONENT.StatusMarks): object | undefined;
}

/** 仅供运行时的身份绑定；组件引用不进入事件或录制。 */
export interface NightLifeScope {
  readonly id: EntityId;
  readonly life: AliveComponent;
  readonly version: number;
}
/** 同一原体的只读查询视图；不复制组件，也不授予修改存活状态的权限。 */
export type NightLifeReadScope = Omit<NightLifeScope, "life"> & {
  readonly life: Readonly<AliveComponent>;
};
export interface NightPoisonClaim {
  readonly source: NightLifeScope;
  readonly target: NightLifeScope;
  readonly isCurrent?: () => boolean;
}

/**
 * 单次已付效果的运行时来源。源原体及目标句柄仅属于本夜，不进入事件或 schema2。
 * 每份效果的因果 ID 是独立 Symbol；捕获局部值只用于诊断描述，不是去重或稳定归档 ID。
 * 创建身份不读 World、时钟或 RNG，也不授予行动资格。
 */
export interface NightIntentOrigin {
  readonly family: "mechanical" | "awakened" | "witch" | "demon-witch" | "lucky" | "black-market" | "scholar-mentor";
  readonly day: number;
  readonly stage: "mechanical_skill" | "mechanical_attack" | "awakened_skill" | "awakened_attack" | "witch" | "lucky" | "black_market_recipient" | "scholar_mentor_bonus";
  readonly actorId: EntityId;
  readonly actorLife: NightLifeReadScope;
  /** 原行动目标；反射不改写它，实际反射落点另存 NightPoisonRoute。 */
  readonly requestedTargetId: EntityId | null;
  /** 创建时绑定的 effect.target.id，与 requestedTargetId 或反射落点分别表达。 */
  readonly effectiveTargetId: EntityId;
  readonly abilityId: string;
  readonly sourceVersion: number;
  readonly targetVersion: number;
  readonly sourceBody: Readonly<AliveComponent>;
  readonly targetBody: Readonly<AliveComponent>;
  /** 每份效果的独立运行时身份；description 只是诊断标签，不能用于去重。 */
  readonly causeId: symbol;
}
export type NightMechanicalIntentKind = "mechanical-shield" | "mechanical-attack" | "mechanical-failure";
export type NightAwakenedIntentKind = "awakened-shield" | "awakened-attack";
export type NightIntentKind = NightMechanicalIntentKind | NightAwakenedIntentKind | "original-poison";
export interface NightMechanicalIntent<K extends NightMechanicalIntentKind = NightMechanicalIntentKind> extends NightMechanicalEffect {
  readonly kind: K;
  readonly origin: NightIntentOrigin;
}
export interface NightAwakenedIntent<K extends NightAwakenedIntentKind = NightAwakenedIntentKind> extends NightAwakenedEffect {
  readonly kind: K;
  readonly origin: NightIntentOrigin;
}
export interface NightOriginalPoisonIntent extends NightPoisonClaim {
  readonly kind: "original-poison";
  readonly origin: NightIntentOrigin;
}
type OriginInput = Omit<NightIntentOrigin, "actorId" | "effectiveTargetId" | "causeId" | "sourceVersion" | "targetVersion" | "sourceBody" | "targetBody">;

// 只标记由本 owner 构造的对象身份，不复制 effects、不按 World 存第二份状态。
// 旧注入对象即使带有同名 getter，也不被当作新 intent 或读取其额外字段。
const ownedIntents = new WeakSet<object>();
function annotateIntent<T extends { readonly target: NightLifeScope }, K extends NightIntentKind>(
  effect: T,
  kind: K,
  origin: OriginInput,
  actorId: EntityId,
): T & Readonly<{ kind: K; origin: NightIntentOrigin }> {
  if (ownedIntents.has(effect)) throw new Error("night_effect_intent_already_owned");
  const effectiveTargetId = effect.target.id;
  const causeId = Symbol(`effect:${origin.day}:${origin.family}:${origin.stage}:${actorId}:${kind}:${origin.abilityId}:${origin.requestedTargetId}:${effectiveTargetId}`);
  const captured = Object.freeze({
    ...origin, actorId, effectiveTargetId, causeId, sourceVersion: origin.actorLife.version, targetVersion: effect.target.version,
    sourceBody: origin.actorLife.life, targetBody: effect.target.life,
  });
  // 只锁定新增协议字段，不冻结原 target/callback；整个 origin 不能被重写绕过原体校验。
  Object.defineProperties(effect, {
    kind: { value: kind, enumerable: true },
    origin: { value: captured, enumerable: true },
  });
  ownedIntents.add(effect);
  return effect as T & Readonly<{ kind: K; origin: NightIntentOrigin }>;
}
/** 机械盾、额外刀与重复守失败保持各自类别及原 owner callback。 */
export function mechanicalNightIntent<K extends NightMechanicalIntentKind>(
  kind: K, effect: NightMechanicalEffect, origin: OriginInput & { readonly family: "mechanical" },
): NightMechanicalIntent<K> {
  return annotateIntent(effect, kind, origin, effect.actorId);
}
/** 觉醒效果不因已付瓶数或首次死亡而丢失原 callback 的专有规则。 */
export function awakenedNightIntent<K extends NightAwakenedIntentKind>(
  kind: K, effect: NightAwakenedEffect, origin: OriginInput & { readonly family: "awakened" },
): NightAwakenedIntent<K> {
  return annotateIntent(effect, kind, origin, effect.actorId);
}
/** 原毒与机械返回毒是不同链路；此 factory 只标记原已付毒。 */
export function originalPoisonIntent(effect: NightPoisonClaim, origin: OriginInput): NightOriginalPoisonIntent {
  return annotateIntent(effect, "original-poison", origin, effect.source.id);
}

/**
 * 在原 target 读取点消费新协议的类别/夜时点/因果链；不替代原 current 或生命重检。
 * 旧 claim/effect 完整保留原读取行为，包括额外 kind/origin getter 从不被调用。
 * 新协议错类别/夜时点属于约束强化；拒绝时不回滚先前已付库存或事实。
 */
export function nightIntentTarget(
  effect: { readonly target: NightLifeScope }, expected: NightIntentKind, night?: () => number | undefined,
): NightLifeScope {
  if (ownedIntents.has(effect)) {
    const intent = effect as Readonly<{ kind: NightIntentKind; origin: NightIntentOrigin; target: NightLifeScope }>;
    if (intent.kind !== expected) throw new Error("night_effect_intent_kind_mismatch");
    const day = night?.();
    if (day !== undefined && intent.origin.day !== day) throw new Error("night_effect_intent_night_mismatch");
    if (!intent.origin.causeId || intent.origin.actorLife.id !== intent.origin.actorId || intent.origin.actorLife.version !== intent.origin.sourceVersion || intent.origin.actorLife.life !== intent.origin.sourceBody)
      throw new Error("night_effect_intent_source_mismatch");
    const target = intent.target;
    if (target.id !== intent.origin.effectiveTargetId || target.version !== intent.origin.targetVersion || target.life !== intent.origin.targetBody)
      throw new Error("night_effect_intent_target_mismatch");
    return target;
  }
  return effect.target;
}

/** 仅在原毒 source 读取位置校验源句柄，不新增施毒者存活或窗口规则。 */
export function nightIntentPoisonSource(claim: NightPoisonClaim): NightLifeScope {
  const source = claim.source;
  if (ownedIntents.has(claim) && source !== (claim as NightOriginalPoisonIntent).origin.actorLife)
    throw new Error("night_effect_intent_source_mismatch");
  return source;
}

/** 在原反射 actorId 读取点核对来源，旧对象仍只执行一次同一属性读取。 */
export function nightIntentMechanicalActor(effect: NightMechanicalEffect): EntityId {
  const actorId = effect.actorId;
  if (ownedIntents.has(effect) && actorId !== (effect as NightMechanicalIntent).origin.actorId)
    throw new Error("night_effect_intent_source_mismatch");
  return actorId;
}
export interface NightFoxInspectionClaim {
  readonly target: NightLifeScope;
  /** 首日警长结算前切换阶段不会撤销原目标绑定。 */
  readonly isTargetCurrent: () => boolean;
  readonly isCurrent: () => boolean;
}
export interface NightGuardClaim {
  readonly isCurrent?: () => boolean;
  readonly contribution?: object;
  readonly target: NightLifeScope;
  readonly marks: StatusMarksComponent;
}
export interface NightMerchantBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export interface NightBlackMarketBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
/** 吞噬反噬是独立攻击，不归入商人效果或梦境死亡。 */
export interface NightRadiantBacklash {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}
export function captureNightLife(world: World, id: EntityId): NightLifeScope | null {
  const life = world.getComponent(id, COMPONENT.Alive),
    version = life && aliveLifeVersion(life);
  return life?.alive && version !== undefined ? { id, life, version } : null;
}
export function sameNightLife(world: NightEffectQuery, scope: NightLifeReadScope): boolean {
  return (
    world.getComponent(scope.id, COMPONENT.Alive) === scope.life &&
    aliveLifeVersion(scope.life) === scope.version
  );
}
export function livingNightLife(world: NightEffectQuery, scope: NightLifeReadScope): boolean {
  return sameNightLife(world, scope) && scope.life.alive;
}

/** 已提交机械效果绑定原体；库存仍由具体机制所有者持有。 */
export interface NightMechanicalEffect {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  /** 只读重检提交者的角色、状态、生命与阶段，不修改原体。 */
  readonly isCurrent: () => boolean;
}
export interface NightMechanicalEffects {
  readonly shields: readonly NightMechanicalEffect[];
  readonly attacks: readonly NightMechanicalEffect[];
  readonly failures: readonly NightMechanicalEffect[];
}
/** 觉醒守护吸收毒药；其额外狼刀按普通保护规则判定。 */
export interface NightAwakenedEffect {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  /** 已付款效果重检原所有者；行动窗口关闭不等于撤销合法已付效果。 */
  readonly isCurrent: () => boolean;
}
export interface NightAwakenedEffects {
  readonly shields: readonly NightAwakenedEffect[];
  readonly attacks: readonly NightAwakenedEffect[];
}
/** 仅全知视角的因果事实；玩家投影不得泄露施毒来源。 */
export interface NightPoisonReflection {
  readonly actorId: EntityId;
  readonly protectedTargetId: EntityId;
  readonly casterId: EntityId;
}
/** 原毒经折叠后的实际去向；反射改变目标，但保留原独立因果身份及原体链。 */
export interface NightPoisonRoute {
  readonly route: "direct" | "reflected";
  readonly origin: NightIntentOrigin;
  readonly targetId: EntityId;
  readonly target: NightLifeReadScope;
}
// 因果链属于本次伤害计划，而非另一份世界状态。非枚举 Symbol 保持原输出／归档形状。
const POISON_ROUTES = Symbol("night_poison_routes");
const NO_POISON_ROUTES: readonly NightPoisonRoute[] = Object.freeze([]);
// 只登记本 owner 的返回对象身份；外部 legacy plan／Proxy 不读取新增 Symbol。
// 路由数据仍仅存于同一计划，这个品牌不保存目标、库存或另一份世界状态。
const ownedDamagePlans = new WeakSet<object>();
export interface MechanicalDamagePlan {
  readonly shields: ReadonlySet<EntityId>;
  readonly directPoisonTargets: ReadonlySet<EntityId>;
  readonly reflectedPoisonTargets: ReadonlySet<EntityId>;
  readonly attacks: ReadonlySet<EntityId>;
  readonly failures: ReadonlySet<EntityId>;
  readonly reflections: readonly NightPoisonReflection[];
  readonly [POISON_ROUTES]?: readonly NightPoisonRoute[];
}
/** Wave／单目标结算的运行时输入；这里只读既有折叠结果，不重查资格或库存。 */
export function nightPoisonRoutes(plan: MechanicalDamagePlan): readonly NightPoisonRoute[] {
  return ownedDamagePlans.has(plan) ? plan[POISON_ROUTES] ?? NO_POISON_ROUTES : NO_POISON_ROUTES;
}
/** owned 路由参与毒的接受；旧集合仍含 owned 目标并作 OR 后备，尚未被路由完全替代。 */
export function nightPoisonRouteTargets(
  plan: MechanicalDamagePlan, targetId: EntityId, route: NightPoisonRoute["route"],
): boolean {
  return nightPoisonRoutes(plan).some((cause) => cause.route === route && cause.targetId === targetId) ||
    (route === "direct" ? plan.directPoisonTargets : plan.reflectedPoisonTargets).has(targetId);
}
function recordOwnedPoisonRoute(
  routes: NightPoisonRoute[], poison: NightPoisonClaim, route: NightPoisonRoute["route"],
  target: NightLifeScope, targetId: EntityId,
): void {
  if (ownedIntents.has(poison))
    routes.push(Object.freeze({ route, origin: (poison as NightOriginalPoisonIntent).origin, targetId, target }));
}
/** 每份原毒只折叠一次；反射毒不再送回盾内，避免递归反射。 */
export function planMechanicalDamage(
  world: NightEffectQuery,
  effects: NightMechanicalEffects | undefined,
  poisons: readonly NightPoisonClaim[] = [],
  absorbedPoisonTargets: ReadonlySet<EntityId> = new Set(),
  intentNight?: () => number | undefined,
): MechanicalDamagePlan {
  // 有效盾按贡献顺序覆盖同一目标，反射事实使用最终选中盾的行动者。
  const shields = new Map<EntityId, NightMechanicalEffect>();
  for (const shield of effects?.shields ?? []) {
    if (shield.isCurrent() && livingNightLife(world, nightIntentTarget(shield, "mechanical-shield", intentNight))) {
      shields.set(nightIntentTarget(shield, "mechanical-shield", intentNight).id, shield);
    }
  }
  const directPoisonTargets = new Set<EntityId>();
  const reflectedPoisonTargets = new Set<EntityId>();
  const reflections: NightPoisonReflection[] = [];
  const poisonRoutes: NightPoisonRoute[] = [];
  // current 回调仅显式 false 撤销已付毒；直接毒不新增源存活门禁，反射才在原位置重检源生命。
  for (const poison of poisons) {
    if (
      poison.isCurrent?.() === false ||
      !livingNightLife(world, nightIntentTarget(poison, "original-poison", intentNight)) ||
      absorbedPoisonTargets.has(nightIntentTarget(poison, "original-poison", intentNight).id)
    )
      continue;
    const shield = shields.get(nightIntentTarget(poison, "original-poison", intentNight).id);
    if (!shield) {
      const target = nightIntentTarget(poison, "original-poison", intentNight), targetId = target.id;
      directPoisonTargets.add(targetId);
      recordOwnedPoisonRoute(poisonRoutes, poison, "direct", target, targetId);
      continue;
    }
    if (livingNightLife(world, nightIntentPoisonSource(poison))) {
      const target = nightIntentPoisonSource(poison), targetId = target.id;
      reflectedPoisonTargets.add(targetId);
      recordOwnedPoisonRoute(poisonRoutes, poison, "reflected", target, targetId);
      reflections.push({
        actorId: nightIntentMechanicalActor(shield),
        protectedTargetId: nightIntentTarget(poison, "original-poison", intentNight).id,
        casterId: nightIntentPoisonSource(poison).id,
      });
    }
  }
  const attacks = new Set<EntityId>();
  const failures = new Set<EntityId>();
  for (const attack of effects?.attacks ?? []) {
    if (attack.isCurrent() && livingNightLife(world, nightIntentTarget(attack, "mechanical-attack", intentNight)))
      attacks.add(nightIntentTarget(attack, "mechanical-attack", intentNight).id);
  }
  for (const failure of effects?.failures ?? []) {
    if (failure.isCurrent() && livingNightLife(world, nightIntentTarget(failure, "mechanical-failure", intentNight)))
      failures.add(nightIntentTarget(failure, "mechanical-failure", intentNight).id);
  }
  const plan: MechanicalDamagePlan = {
    shields: new Set(shields.keys()),
    directPoisonTargets,
    reflectedPoisonTargets,
    attacks,
    failures,
    reflections,
  };
  Object.defineProperty(plan, POISON_ROUTES, { value: Object.freeze(poisonRoutes) });
  ownedDamagePlans.add(plan);
  return plan;
}

/** 有限纯白查验规则的原所有者与目标绑定。 */
export interface NightInspectionAttack {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  readonly cause: DeathCause.PureWhiteInspection | DeathCause.WolfWitchInspection;
  readonly isCurrent: () => boolean;
}

/** 恶灵骑士反击在原行动接受时付款，于夜末按原体绑定结算。 */
export interface NightRetaliationAttack {
  readonly actorId: EntityId;
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}

/** 持续被动夜间免疫保留原生命与角色授权。 */
export interface NightImmunityClaim {
  readonly target: NightLifeScope;
  readonly isCurrent: () => boolean;
}

/**
 * 负责丘比特完整选择数据的原初始化、同槽读取、玩家投影与库存／选择写入。
 * 输入是原初始化角色及上下文，或已获准提交的原状态和配对编号；输出保留原槽引用与独立玩家选择视图。
 * 初始化先查原槽，先求值赋值左值的容器，再读取政策并安装；提交先消费剩余次数，再复制配对数组并写选择，失败不回滚。
 * 本槽不新增 live schema、深冻结或档案编码；关系、生命、Victory、窗口和许可仍由原夜阶段／关系 owner 持有。
 */
import type { CupidReadState, CupidState } from "@ai-werewolf-arena/game-contract";
import { playerDataField } from "../player-state-data";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent, RoleInitContext } from "../contracts";
export function getCupidState(role: RoleComponent | undefined): CupidReadState | undefined {
  return (role as { readonly privateState: { readonly cupid?: unknown } } | undefined)?.privateState
    .cupid as CupidReadState | undefined;
}
export function projectCupidState(
  state: CupidReadState,
): import("@ai-werewolf-arena/game-contract/player-state-views").PlayerCupidState {
  const policy = playerDataField(state, "policy"),
    choice = playerDataField(state, "choice"),
    pair = playerDataField(choice, "pairIds");
  // 数组用自己的数据属性读取；共用对象读取器本来拒绝数组，不能因此执行外来编号访问器。
  const pairField = (key: string): unknown => {
    if (!Array.isArray(pair)) return undefined;
    const field = Object.getOwnPropertyDescriptor(pair, key);
    return field && Object.hasOwn(field, "value") ? field.value : undefined;
  };
  const first = pairField("0"),
    second = pairField("1");
  const positive = (id: unknown): id is number =>
    typeof id === "number" && Number.isSafeInteger(id) && id > 0;
  return {
    policy: policy === "lui_meme_lovers_only_v1" ? policy : "netease_2017_cupid_follows_lovers_v1",
    remaining: playerDataField(state, "remaining") === 1 ? 1 : 0,
    choice:
      playerDataField(choice, "day") === 1 &&
      Array.isArray(pair) &&
      pairField("length") === 2 &&
      positive(first) &&
      positive(second) &&
      first !== second
        ? { day: 1, pairIds: [first, second] }
        : null,
  };
}

/** 原完整初始化：槽不存在时才建初态，不提前读取政策或把整个私有容器复制／冻结。 */
export function installCupidState(role: RoleInitializationComponent, ctx: Pick<RoleInitContext, "boardConfig">): void {
  if (!getCupidState(role))
    role.privateState.cupid = {
      policy: ctx.boardConfig?.cupid?.policy ?? "netease_2017_cupid_follows_lovers_v1",
      remaining: 1,
      choice: null,
    };
}

/** 调用前关系已由原 owner 绑定；次数写入后的配对复制或 choice setter 失败不撤回已绑定关系或补发事实。 */
export function commitCupidChoice(state: CupidReadState, pairIds: [number, number]): void {
  (state as Pick<CupidState, "remaining">).remaining = 0;
  (state as Pick<CupidState, "choice">).choice = { day: 1, pairIds: [...pairIds] };
}

/**
 * 负责混血儿完整选择数据的初态、原槽初始化／读取、首夜库存条件与玩家投影。
 * 输入是原初始化角色，或已获准提交的状态、日次和榜样编号；输出保留同一存储对象与独立选择副本。
 * 初始化保查槽→左值容器→初态创建顺序；选择先消费次数，再写 choice，随后 Victory 安装仍由原夜阶段负责。
 * 本槽不改变 live 接受集合，不新增 schema、生命许可、深冻结或私有档案 codec；失败保留已经完成的字段前缀。
 */
import type { HybridState, HybridReadState } from "@ai-werewolf-arena/game-contract";
import type { PlayerHybridState } from "@ai-werewolf-arena/game-contract/player-state-views";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent } from "../contracts";
export const freshHybridState = (): HybridState => ({ remaining: 1, choice: null });
export function getHybridState(role: RoleComponent | undefined): HybridReadState | undefined {
  return (role as { readonly privateState: { readonly hybrid?: unknown } } | undefined)
    ?.privateState.hybrid as HybridReadState | undefined;
}
export function projectHybridState(state: HybridReadState): PlayerHybridState {
  return {
    remaining: state.remaining,
    choice: state.choice ? { day: state.choice.day, targetId: state.choice.targetId } : null,
  };
}
export function canChooseExemplar(state: HybridReadState, day: number): boolean {
  return day === 1 && state.remaining === 1 && state.choice === null;
}

/** 原完整初始化：保留既有槽；原容器左值在 fresh 初态调用之前读取，不另建镜像。 */
export function installHybridState(role: RoleInitializationComponent): void {
  if (!getHybridState(role)) role.privateState.hybrid = freshHybridState();
}

/** 原胜利归属对象已在调用前构造；这里按原次序写两字段，不安装 Victory，也不在后续安装失败时退款。 */
export function commitHybridChoice(state: HybridReadState, day: number, targetId: number): void {
  (state as Pick<HybridState, "remaining">).remaining = 0;
  (state as Pick<HybridState, "choice">).choice = { day, targetId };
}

/**
 * Owns Wolf Beauty's existing private-state slot and ordinary charm history writes.
 * Inputs are the original role or captured state plus the accepted nullable target/day;
 * outputs retain the same stored reference, assignment order and partial writes.
 * State data retains death-link policy, nullable target/day and nullable-target history.
 * Callers own target qualification, charm binding and public/private publication;
 * this owner never repeats those checks, refunds effects or changes death policy.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type { WolfBeautyState, WolfBeautyReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { EntityId } from "@ai-werewolf-arena/game-contract";

export function setWolfBeautyState(
  roleComp: RoleComponent,
  state: WolfBeautyState,
): WolfBeautyReadState {
  (roleComp.privateState as { wolf_beauty: WolfBeautyState })["wolf_beauty"] = state;
  return state;
}

export function getWolfBeautyState(roleComp: RoleComponent): WolfBeautyReadState | undefined {
  return (roleComp.privateState as { readonly wolf_beauty?: unknown })["wolf_beauty"] as
    WolfBeautyReadState | undefined;
}

/** The caller retains every preflight and subsequent use/effect/publication operation. */
export function recordCharmSelection(
  state: WolfBeautyReadState,
  targetId: EntityId | null,
  day: number,
): void {
  (state as { targetId: EntityId | null }).targetId = targetId;
  (state as { lastActedDay: number | null }).lastActedDay = day;
  (state.history as WolfBeautyState["history"]).push({ day, targetId });
}

/**
 * 负责狼美人魅惑绑定、领取／阻断／实际死亡回执和原体当前性查询。
 * 输入为原源／目标引用及死亡原因；输出为仍当前的关系和具体阶段结果，bindings 是唯一权威状态。
 * resolved 表示牵连已经领取，applied 表示目标确实死亡；梦阻断仍消耗领取，不能退款重触发。
 * 回执只保同一绑定的不可伪造运行时引用，不复制状态或授予死亡权限；不标死或发布事实。
 * 规则来源：docs/rules/awa-wolf-beauty-v1.md，各政策保留其独立来源抑制。
 */
import type { WolfBeautyReadState as WolfBeautyState } from "@ai-werewolf-arena/game-contract";

import { AliveComponent, aliveLifeVersion } from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  Role,
  DeathCause,
  type DeathSources,
  type EntityId,
} from "../../../../core/domain/model";
import type { World } from "../../../../core/domain/world";
import { getWolfBeautyState } from "./state";

export interface CharmBinding {
  readonly actorId: EntityId;
  readonly targetId: EntityId;
  readonly role: Readonly<RoleComponent>;
  readonly state: WolfBeautyState;
  readonly actorLife: Readonly<AliveComponent>;
  readonly actorVersion: number | undefined;
  readonly targetLife: Readonly<AliveComponent>;
  readonly targetVersion: number | undefined;
  readonly resolved: boolean;
  readonly applied: boolean;
  readonly deathLinkPolicy: import("../../../../core/domain/board").BeautyDeathLinkPolicy;
}
const bindings = new WeakMap<World, Map<EntityId, CharmBinding>>();

// 回执只是本次触发的阶段结果；关系库存／原体资格始终由上面的单一 bindings 持有。
// 私有 Symbol 不进入 JSON，WeakSet 只标记身份，不保存第二份关系或 World 状态。
const RECEIPT_BRAND = Symbol("charm_receipt_brand");
const RECEIPT_BINDING = Symbol("charm_receipt_binding");
const issuedReceipts = new WeakSet<object>();
type CharmReceipt<K extends "claimed" | "blocked" | "applied"> = Readonly<{
  kind: K;
  [RECEIPT_BRAND]: true;
}>;
export type CharmClaimReceipt = CharmReceipt<"claimed">;
export type CharmBlockedReceipt = CharmReceipt<"blocked">;
export type CharmAppliedReceipt = CharmReceipt<"applied">;
export type CharmProtectionReceipt = CharmClaimReceipt | CharmBlockedReceipt;

function issueReceipt<K extends CharmProtectionReceipt["kind"] | "applied">(
  kind: K,
  binding: CharmBinding,
): CharmReceipt<K> {
  const receipt: CharmReceipt<K> = { kind, [RECEIPT_BRAND]: true };
  Object.defineProperty(receipt, RECEIPT_BINDING, { value: binding });
  issuedReceipts.add(receipt);
  return Object.freeze(receipt);
}
export function bindCharm(world: World, actorId: EntityId, targetId: EntityId | null): void {
  const map = bindings.get(world) ?? new Map<EntityId, CharmBinding>();
  bindings.set(world, map);
  map.delete(actorId);
  if (targetId === null) return;
  const role = world.getComponent(actorId, COMPONENT.Role)!,
    state = getWolfBeautyState(role)!,
    actorLife = world.getComponent(actorId, COMPONENT.Alive)!,
    targetLife = world.getComponent(targetId, COMPONENT.Alive)!;
  map.set(actorId, {
    actorId,
    targetId,
    role,
    state,
    actorLife,
    actorVersion: aliveLifeVersion(actorLife),
    targetLife,
    targetVersion: aliveLifeVersion(targetLife),
    resolved: false,
    applied: false,
    deathLinkPolicy: state.deathLinkPolicy ?? "awa_exile_poison_v1",
  });
}
function current(world: World, binding: CharmBinding): boolean {
  return (
    world.getComponent(binding.actorId, COMPONENT.Role) === binding.role &&
    binding.role.role === Role.WolfBeauty &&
    getWolfBeautyState(binding.role) === binding.state &&
    binding.state.targetId === binding.targetId &&
    (binding.state.deathLinkPolicy ?? "awa_exile_poison_v1") === binding.deathLinkPolicy &&
    world.getComponent(binding.actorId, COMPONENT.Alive) === binding.actorLife &&
    binding.actorVersion !== undefined &&
    aliveLifeVersion(binding.actorLife) ===
      binding.actorVersion + (binding.actorLife.alive ? 0 : 1) &&
    world.getComponent(binding.targetId, COMPONENT.Alive) === binding.targetLife &&
    binding.targetVersion !== undefined &&
    aliveLifeVersion(binding.targetLife) ===
      binding.targetVersion + (binding.targetLife.alive ? 0 : 1)
  );
}
/** 同一 current 函数的具名查询绑定，不建包装、关系副本或新授权；各字段仍按原短路顺序晚读。 */
export { current as isCharmBindingCurrent };

export function activeCharm(world: World, actorId: EntityId): CharmBinding | null {
  const binding = bindings.get(world)?.get(actorId);
  return binding && !binding.resolved && current(world, binding) ? binding : null;
}
/** 在追加死因或标死之前同步领取；同波原体允许首次死亡版本，不接受复活或替身。 */
function claimCharm(
  world: World,
  binding: CharmBinding,
  eligibleDead: ReadonlySet<EntityId>,
): boolean {
  if (
    activeCharm(world, binding.actorId) !== binding ||
    binding.actorLife.alive ||
    (!binding.targetLife.alive && !eligibleDead.has(binding.targetId))
  )
    return false;
  (binding as { resolved: boolean }).resolved = true;
  return true;
}
/**
 * 具体触发流程拥有来源政策→原体领取→夜梦阻断分类；World 与保护查询都延迟到原表达式位置。
 * 不提前获取 World，permit 不合格时也不读保护；阻断／查询抛错仍保已经 resolved 的原付款。
 */
export function attemptCharmTrigger(
  binding: CharmBinding,
  sources: DeathSources,
  nativeHunterShotTargets: ReadonlySet<EntityId>,
  eligibleDead: ReadonlySet<EntityId>,
  world: () => World,
  blocksNightCharm: () => unknown,
): CharmProtectionReceipt | null {
  if (
    !permitsCharm(
      sources[binding.actorId] ?? [],
      binding.deathLinkPolicy,
      nativeHunterShotTargets.has(binding.actorId),
    ) ||
    !claimCharm(world(), binding, eligibleDead)
  )
    return null;
  return issueReceipt(blocksNightCharm() ? "blocked" : "claimed", binding);
}

/** 实际目标标死之后提交 applied；回执不能替代原同绑定、角色、政策及生命版本检查。 */
export function commitCharmDeath(
  world: World,
  receipt: CharmClaimReceipt,
): CharmAppliedReceipt | null {
  if (!issuedReceipts.has(receipt) || receipt.kind !== "claimed") return null;
  const binding = (receipt as CharmClaimReceipt & { readonly [RECEIPT_BINDING]: CharmBinding })[
    RECEIPT_BINDING
  ];
  if (
    bindings.get(world)?.get(binding.actorId) !== binding ||
    !binding.resolved ||
    !current(world, binding) ||
    binding.targetLife.alive
  )
    return null;
  (binding as { applied: boolean }).applied = true;
  return issueReceipt("applied", binding);
}
export function permitsCharm(
  sources: readonly DeathCause[],
  policy: import("../../../../core/domain/board").BeautyDeathLinkPolicy = "awa_exile_poison_v1",
  nativeHunterShot = false,
): boolean {
  // S7 仅规定放逐／原生猎人；未定义的复合死因先按抑制处理，不把赠枪当原生枪。
  if (policy === "heroes_s7_2017_exile_hunter_v1")
    return (
      sources.length > 0 &&
      sources.every(
        (source) => source === DeathCause.Exile || (source === DeathCause.Shot && nativeHunterShot),
      )
    );
  if (policy !== "awa_exile_poison_v1") return false;
  return (
    !sources.includes(DeathCause.Lovers) &&
    !sources.includes(DeathCause.Duel) &&
    !sources.includes(DeathCause.Dream) &&
    sources.some((source) => source === DeathCause.Exile || source === DeathCause.Poison)
  );
}
